// Generates src/generated/assets.ts: the stylesheet and the SQL migrations as string constants, so the
// deployed bundle (e.g. on Vercel) never reads files at runtime. tests/assets.test.ts fails when the
// generated file is out of date: run `npm run gen:assets` after changing db/migrations or app.css.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { explainers, seconds } from "../src/landing/presenters.ts";

export function buildAssets(root = fileURLToPath(new URL("..", import.meta.url))): string {
  const dir = `${root}/db/migrations`;
  const files = readdirSync(dir).filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort();
  const migrations = files.map((name) => ({ name, sql: readFileSync(`${dir}/${name}`, "utf8") }));
  const css = readFileSync(`${root}/src/shared/app.css`, "utf8");
  const landingCss = readFileSync(`${root}/src/landing/landing.css`, "utf8");
  const landingJs = readFileSync(`${root}/src/landing/landing.js`, "utf8");
  const font = readFileSync(`${root}/src/shared/fonts/manrope-latin.woff2`).toString("base64");
  return [
    "// GENERATED by scripts/gen-assets.ts from db/migrations, src/shared/app.css, src/landing/landing.css and the Manrope font. Do not edit by hand.",
    `export const CSS: string = ${JSON.stringify(css)};`,
    `export const LANDING_CSS: string = ${JSON.stringify(landingCss)};`,
    `export const LANDING_JS: string = ${JSON.stringify(landingJs)};`,
    "// Manrope (SIL Open Font License 1.1, src/shared/fonts/MANROPE-OFL.txt), latin subset, variable weight.",
    `export const MANROPE_WOFF2_BASE64: string = ${JSON.stringify(font)};`,
    `export const MIGRATIONS: readonly { name: string; sql: string }[] = ${JSON.stringify(migrations, null, 1)};`,
    "",
  ].join("\n");
}

/** docs/PRESENTER_SCRIPTS.md, generated from src/landing/agents-copy.ts (the page shows the same lines as captions). */
export function buildPresenterDoc(): string {
  const words = (lines: string[]) => lines.join(" ").split(/\s+/).length;
  const out = [
    "# Presenter scripts (English and French)",
    "",
    "_Generated by `npm run gen:assets` from `src/landing/agents-copy.ts`. Edit the scripts there, not here. French: review by a fluent reader required before publication._",
    "",
    "One explainer per AI agent, in both languages. On the page each explainer **speaks**: a recorded file when one exists, otherwise the visitor's device reads the script with its most natural voice, with captions.",
    "",
    "## What plays today",
    "",
    "Every explainer ships with an **AI-generated voice** (Piper, open-source text-to-speech: English `en_US-ljspeech-high`, French `fr_FR-siwis-medium`; licences in docs/REFERENCE_CHECKS.md R66). Files: `public/audio/<lang>/<key>.mp3`, line timings in `src/landing/narration.ts`. After changing a script, regenerate them: `npx tsx scripts/export-scripts.ts > /tmp/scripts.json && python3 scripts/gen-narration.py <piper> <voices-dir> /tmp/scripts.json`.",
    "",
    "## Recording natural voices (to replace the AI voice)",
    "",
    "- **Who:** a real person (owner or staff, English and French speakers) or a natural neural voice service. Use a Canadian French voice for French. Never use a real person's voice or likeness without their written permission; label AI voices and avatars as AI.",
    "- **Narration only (audio):** MP3, 44.1 kHz, mono, clear room. Files: `<lang>/<key>.mp3` (for example `fr/booking.mp3`). Set `BAI_PRESENTER_AUDIO_BASE` to the folder's address and redeploy.",
    "- **Video explainers:** 1920×1080 MP4 (H.264, AAC) plus a 1280×720 JPG poster: `<lang>/<key>.mp4` and `<lang>/<key>.jpg`. Set `BAI_PRESENTER_VIDEO_BASE`. Video takes precedence over narration.",
    "- **Words:** read the script exactly. Captions (`/captions/<lang>/<key>.vtt`) are generated from it; if you change the words, change them in `src/landing/agents-copy.ts` too.",
    "- **Claims:** add no numbers, customer names, results or promises. Messages, posts and payments are not sent during the pilot.",
    "",
  ];
  const en = explainers("en"); const fr = explainers("fr");
  en.forEach((e, i) => {
    const f = fr[i]!;
    out.push(`## ${e.name} / ${f.name} — \`${e.key}\``, "",
      `- **Files:** \`en/${e.key}.mp3\` · \`fr/${e.key}.mp3\` (or \`.mp4\` + \`.jpg\`)`,
      `- **Length:** about ${seconds("en", e.lines)} s in English (${words(e.lines)} words), ${seconds("fr", f.lines)} s in French (${words(f.lines)} words)`,
      "", "**English**", "", ...e.lines.map((l) => `> ${l}`), "", "**Français**", "", ...f.lines.map((l) => `> ${l}`), "");
  });
  return out.join("\n");
}

if (process.argv[1]?.endsWith("gen-assets.ts")) {
  const root = fileURLToPath(new URL("..", import.meta.url));
  mkdirSync(`${root}/src/generated`, { recursive: true });
  writeFileSync(`${root}/src/generated/assets.ts`, buildAssets(root));
  writeFileSync(`${root}/docs/PRESENTER_SCRIPTS.md`, buildPresenterDoc());
  console.log("wrote src/generated/assets.ts");
}
